-- ============================================================================
-- V424 : Exemples-modèles EO réalistes (dialogues/monologues type examen)
-- ============================================================================
-- 1 exemple par tâche EO, en SIMULATION proche du réel, à la BONNE DURÉE :
--   * T1 (entretien dirigé)  : dialogue examinateur <-> candidat (~3 min)
--   * T2 (jeu de rôle)        : dialogue candidat <-> agent (~3 min 30)
--   * T3 (opinion)            : monologue du candidat (~3 min 30)
--
-- Deux champs texte :
--   * contenu   = transcription lisible ([Examinateur]/[Candidat]...)
--   * ssml_text = SSML multi-voix prêt pour Azure (généré en audio par le
--                 batch admin ; cf. SPEC_audio_exemples_EO.md +
--                 AJUSTEMENT_ssml_text_examples.md).
--
-- Voix : Denise = examinateur / agent ; Henri = candidat. T3 = Henri seul.
-- Rattachement : task_id = ligne B1 du bon (epreuve, tache_numero) [V130].
-- audio_url reste NULL jusqu'à génération par le batch admin.
-- ============================================================================

DO $$
DECLARE
eo_t1 UUID;
    eo_t2 UUID;
    eo_t3 UUID;
BEGIN
SELECT id INTO eo_t1 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 1 AND niveau_cible = 'B1' LIMIT 1;
SELECT id INTO eo_t2 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 2 AND niveau_cible = 'B1' LIMIT 1;
SELECT id INTO eo_t3 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 3 AND niveau_cible = 'B1' LIMIT 1;

-- ========================================================================
-- EO TÂCHE 1 — ENTRETIEN DIRIGÉ (~3 min)
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
             eo_t1,
             'Entretien dirigé : un cuisinier se présente',
             'Un échange réaliste d''environ 3 minutes : le candidat se présente et l''examinateur relance avec des questions ouvertes.',
             E'[Examinateur] Bonjour. Pour commencer cette première partie, est-ce que vous pouvez vous présenter, s''il vous plaît ?\n[Candidat] Bonjour. Oui, avec plaisir. Je m''appelle Samuel, j''ai 34 ans et je suis camerounais. Je suis né à Douala, mais j''habite à Nantes depuis maintenant cinq ans.\n[Examinateur] Très bien. Et qu''est-ce que vous faites dans la vie ?\n[Candidat] Je suis cuisinier dans un restaurant du centre-ville. Au début, j''ai commencé comme simple commis de cuisine, et petit à petit, grâce à mon travail, je suis devenu chef de partie. J''aime beaucoup ce métier, parce qu''il est créatif et qu''on ne s''ennuie jamais. Chaque jour est différent.\n[Examinateur] C''est intéressant. Et qu''est-ce qui vous a amené en France, au départ ?\n[Candidat] À l''origine, je suis venu pour faire des études en gestion à l''université. Pendant ces années, j''ai rencontré ma compagne, qui est française. Nous nous sommes installés ensemble à Nantes, et aujourd''hui, nous avons une petite fille de deux ans. C''est pour cela que j''ai décidé de construire ma vie ici.\n[Examinateur] Je comprends. Parlez-moi un peu de vos loisirs. Comment occupez-vous votre temps libre ?\n[Candidat] J''ai deux grandes passions. La première, c''est le football : je joue tous les dimanches matin avec une équipe d''amis, c''est un vrai moment de détente. La deuxième, évidemment, c''est la cuisine. Même à la maison, j''aime tester de nouvelles recettes et faire découvrir à ma famille les plats traditionnels de mon pays.\n[Examinateur] Et si vous pensez à l''avenir, quels sont vos projets ?\n[Candidat] Mon plus grand rêve, c''est d''ouvrir mon propre restaurant. J''aimerais proposer une cuisine originale, qui mélange les saveurs françaises et africaines. Je pense qu''il y a vraiment quelque chose de beau à faire avec ce mélange de cultures. C''est aussi pour cette raison que je passe le TCF aujourd''hui : je prépare une demande de naturalisation, car je me sens désormais chez moi en France.\n[Examinateur] Eh bien, je vous remercie. C''était une présentation très claire et complète.\n[Candidat] Merci à vous.',
             E'Ce modèle montre un entretien réussi : le candidat ne récite pas un texte appris par cœur, il répond précisément à chaque question et développe avec des détails concrets. Remarquez : (1) il varie les temps (présent pour le quotidien, passé composé pour le parcours) ; (2) il donne des exemples vivants ("commis → chef de partie", "football le dimanche") au lieu de généralités ; (3) il relie naturellement sa motivation au TCF à la fin. À l''examen, l''examinateur vous relancera : ne répondez jamais par un seul mot, enrichissez chaque réponse avec une raison ou un exemple. C''est le candidat qui doit parler le plus.',
             E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Bonjour. Pour commencer cette première partie, est-ce que vous pouvez vous présenter, s''il vous plaît ?</prosody><break time="700ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour. Oui, avec plaisir. Je m''appelle Samuel, j''ai 34 ans et je suis camerounais. Je suis né à Douala, mais j''habite à Nantes depuis maintenant cinq ans.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Très bien. Et qu''est-ce que vous faites dans la vie ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je suis cuisinier dans un restaurant du centre-ville. Au début, j''ai commencé comme simple commis de cuisine, et petit à petit, grâce à mon travail, je suis devenu chef de partie. J''aime beaucoup ce métier, parce qu''il est créatif et qu''on ne s''ennuie jamais. Chaque jour est différent.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">C''est intéressant. Et qu''est-ce qui vous a amené en France, au départ ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">À l''origine, je suis venu pour faire des études en gestion à l''université. Pendant ces années, j''ai rencontré ma compagne, qui est française. Nous nous sommes installés ensemble à Nantes, et aujourd''hui, nous avons une petite fille de deux ans. C''est pour cela que j''ai décidé de construire ma vie ici.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Je comprends. Parlez-moi un peu de vos loisirs. Comment occupez-vous votre temps libre ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">J''ai deux grandes passions. La première, c''est le football : je joue tous les dimanches matin avec une équipe d''amis, c''est un vrai moment de détente. La deuxième, évidemment, c''est la cuisine. Même à la maison, j''aime tester de nouvelles recettes et faire découvrir à ma famille les plats traditionnels de mon pays.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et si vous pensez à l''avenir, quels sont vos projets ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mon plus grand rêve, c''est d''ouvrir mon propre restaurant. J''aimerais proposer une cuisine originale, qui mélange les saveurs françaises et africaines. Je pense qu''il y a vraiment quelque chose de beau à faire avec ce mélange de cultures. C''est aussi pour cette raison que je passe le TCF aujourd''hui : je prépare une demande de naturalisation, car je me sens désormais chez moi en France.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Eh bien, je vous remercie. C''était une présentation très claire et complète.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci à vous.</prosody></voice></speak>',
             '["Examinateur : invitation à se présenter", "Identité (nom, âge, origine, ville)", "Travail + parcours développé (commis -> chef)", "Venue en France + situation familiale", "Loisirs détaillés (football, cuisine)", "Projets + lien avec le TCF et la naturalisation", "Clôture"]'::jsonb,
             'B1', 0
         );

-- ========================================================================
-- EO TÂCHE 2 — JEU DE RÔLE (~3 min 30)
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
             eo_t2,
             'Jeu de rôle : louer un appartement',
             'Une interaction réaliste d''environ 3 min 30 : le candidat appelle une agence, échange avec l''agent et fixe une visite.',
             E'[Agent] Agence Belle Vue, bonjour, que puis-je faire pour vous ?\n[Candidat] Bonjour Madame. Je vous appelle au sujet de l''appartement deux-pièces que j''ai vu sur votre annonce, dans le quartier des Halles. Est-ce qu''il est toujours disponible ?\n[Agent] Oui, il est encore libre. C''est un 45 mètres carrés dans un quartier calme, au troisième étage avec ascenseur.\n[Candidat] Ah, très bien, l''ascenseur c''est pratique. Pouvez-vous me dire quel est le montant du loyer, et si les charges sont comprises dedans ?\n[Agent] Le loyer est de 780 euros par mois. Les charges sont en plus, elles s''élèvent à environ 50 euros, ce qui comprend l''eau et l''entretien des parties communes.\n[Candidat] D''accord, je note. Et est-ce que l''appartement est meublé, ou est-ce qu''il faut que j''apporte mes propres meubles ?\n[Agent] Il est loué vide, donc il faudra prévoir vos meubles. En revanche, la cuisine est entièrement équipée.\n[Candidat] Parfait. Et le quartier, est-il bien desservi par les transports en commun ? C''est important pour moi car je travaille à l''autre bout de la ville.\n[Agent] Oui, tout à fait. Il y a un arrêt de bus juste devant l''immeuble, et la station de tramway est à cinq minutes à pied seulement.\n[Candidat] Très bien, ça me convient. Quels documents est-ce qu''il faut préparer pour constituer le dossier ?\n[Agent] Il me faut une pièce d''identité, vos trois derniers bulletins de salaire, votre contrat de travail et votre dernier avis d''imposition.\n[Candidat] D''accord, j''ai tous ces documents. Est-ce qu''il serait possible de visiter l''appartement cette semaine ?\n[Agent] Bien sûr. Seriez-vous disponible samedi matin, vers dix heures ?\n[Candidat] Samedi à dix heures, c''est parfait pour moi. Pouvez-vous me donner l''adresse exacte ?\n[Agent] Oui, c''est au 12 rue des Halles. Je vous attendrai devant l''entrée.\n[Candidat] Très bien, je vous remercie beaucoup pour toutes ces informations. À samedi, alors.\n[Agent] Je vous en prie. À samedi, bonne journée !\n[Candidat] Bonne journée à vous aussi, au revoir.',
             E'Ce modèle illustre une interaction complète et fluide. Points à imiter : (1) le candidat ouvre poliment et explique tout de suite la raison de son appel ; (2) il pose des questions variées et utiles (prix, charges, meublé ou non, transports, documents, visite) au lieu d''une seule ; (3) il réagit aux réponses ("l''ascenseur c''est pratique", "c''est important pour moi car...") plutôt que d''enchaîner mécaniquement ; (4) il conclut en fixant un rendez-vous concret et en demandant l''adresse. À l''examen, c''est l''examinateur qui joue l''agent : votre rôle est de mener l''échange et d''obtenir les informations, pas d''attendre passivement.',
             E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Agence Belle Vue, bonjour, que puis-je faire pour vous ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour Madame. Je vous appelle au sujet de l''appartement deux-pièces que j''ai vu sur votre annonce, dans le quartier des Halles. Est-ce qu''il est toujours disponible ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, il est encore libre. C''est un 45 mètres carrés dans un quartier calme, au troisième étage avec ascenseur.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ah, très bien, l''ascenseur c''est pratique. Pouvez-vous me dire quel est le montant du loyer, et si les charges sont comprises dedans ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Le loyer est de 780 euros par mois. Les charges sont en plus, elles s''élèvent à environ 50 euros, ce qui comprend l''eau et l''entretien des parties communes.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, je note. Et est-ce que l''appartement est meublé, ou est-ce qu''il faut que j''apporte mes propres meubles ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Il est loué vide, donc il faudra prévoir vos meubles. En revanche, la cuisine est entièrement équipée.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Parfait. Et le quartier, est-il bien desservi par les transports en commun ? C''est important pour moi car je travaille à l''autre bout de la ville.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, tout à fait. Il y a un arrêt de bus juste devant l''immeuble, et la station de tramway est à cinq minutes à pied seulement.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, ça me convient. Quels documents est-ce qu''il faut préparer pour constituer le dossier ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Il me faut une pièce d''identité, vos trois derniers bulletins de salaire, votre contrat de travail et votre dernier avis d''imposition.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, j''ai tous ces documents. Est-ce qu''il serait possible de visiter l''appartement cette semaine ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr. Seriez-vous disponible samedi matin, vers dix heures ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Samedi à dix heures, c''est parfait pour moi. Pouvez-vous me donner l''adresse exacte ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, c''est au 12 rue des Halles. Je vous attendrai devant l''entrée.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, je vous remercie beaucoup pour toutes ces informations. À samedi, alors.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Je vous en prie. À samedi, bonne journée !</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonne journée à vous aussi, au revoir.</prosody></voice></speak>',
             '["Agent ouvre l''échange", "Objet de l''appel + disponibilité", "Loyer + charges détaillées", "Meublé ou vide + cuisine", "Transports + réaction personnelle", "Documents du dossier", "Demande de visite + créneau + adresse", "Clôture polie"]'::jsonb,
             'B1', 0
         );

-- ========================================================================
-- EO TÂCHE 3 — OPINION (monologue ~3 min 30)
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
             eo_t3,
             'Donner son opinion : les transports en commun gratuits',
             'Un monologue argumenté d''environ 3 min 30, structuré comme à l''examen : introduction, arguments, objection, conclusion.',
             E'[Candidat] Aujourd''hui, je voudrais parler de la question des transports en commun gratuits. C''est un sujet dont on entend beaucoup parler dans les grandes villes, et je trouve que c''est une idée vraiment intéressante, même si elle mérite réflexion. Je vais donc vous donner mon point de vue.\n\nPour commencer, je pense que rendre les transports gratuits aurait surtout des avantages. Le premier argument, c''est l''environnement. Si les bus et les trams sont gratuits, beaucoup de gens vont laisser leur voiture à la maison. Par conséquent, il y aura moins de pollution dans l''air et moins d''embouteillages aux heures de pointe. Par exemple, dans certaines villes qui ont déjà testé la gratuité, on a constaté que le nombre de voitures dans le centre avait nettement diminué en quelques mois seulement.\n\nLe deuxième argument, c''est la justice sociale. Pour beaucoup de personnes, le prix des transports représente une vraie difficulté. Je pense notamment aux étudiants, aux personnes âgées ou aux familles qui ont de petits revenus. Grâce à la gratuité, tout le monde pourrait se déplacer librement, que ce soit pour aller travailler, pour étudier, ou simplement pour aller voir un médecin. C''est une question d''égalité entre les citoyens.\n\nBien sûr, on pourrait m''objecter que tout cela coûte très cher à la collectivité. Et c''est vrai, je le reconnais. Si personne ne paie son ticket, il faut bien que cet argent vienne de quelque part : en général, ce sont les impôts des habitants. Certaines personnes pensent aussi que la gratuité pourrait entraîner des dégradations ou un manque de respect du matériel.\n\nCependant, malgré ces objections, je reste convaincu que les bénéfices sont plus importants que les inconvénients. À condition que le réseau soit bien organisé et correctement financé, la gratuité peut vraiment améliorer la vie quotidienne des habitants et protéger l''environnement. Pour conclure, je dirais que je suis plutôt favorable à cette idée, mais qu''il faut la mettre en place progressivement, et l''adapter à la taille et aux moyens de chaque ville. Voilà, c''était mon opinion sur ce sujet.',
             E'Ce modèle suit exactement la structure attendue à la tâche 3 : (1) une introduction qui annonce le sujet et la position ; (2) deux arguments clairs, chacun illustré ("le premier argument... par exemple...", "le deuxième argument...") ; (3) une objection honnêtement présentée ("on pourrait m''objecter que...") ; (4) une réponse à cette objection ; (5) une conclusion nuancée. Remarquez les connecteurs logiques (pour commencer, par conséquent, cependant, à condition que + subjonctif, pour conclure) qui structurent tout le discours. Pour réussir, ne donnez pas seulement votre avis : justifiez-le avec des exemples et anticipez l''avis contraire.',
             E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Aujourd''hui, je voudrais parler de la question des transports en commun gratuits. C''est un sujet dont on entend beaucoup parler dans les grandes villes, et je trouve que c''est une idée vraiment intéressante, même si elle mérite réflexion. Je vais donc vous donner mon point de vue.<break time="600ms"/>Pour commencer, je pense que rendre les transports gratuits aurait surtout des avantages. Le premier argument, c''est l''environnement. Si les bus et les trams sont gratuits, beaucoup de gens vont laisser leur voiture à la maison. Par conséquent, il y aura moins de pollution dans l''air et moins d''embouteillages aux heures de pointe. Par exemple, dans certaines villes qui ont déjà testé la gratuité, on a constaté que le nombre de voitures dans le centre avait nettement diminué en quelques mois seulement.<break time="600ms"/>Le deuxième argument, c''est la justice sociale. Pour beaucoup de personnes, le prix des transports représente une vraie difficulté. Je pense notamment aux étudiants, aux personnes âgées ou aux familles qui ont de petits revenus. Grâce à la gratuité, tout le monde pourrait se déplacer librement, que ce soit pour aller travailler, pour étudier, ou simplement pour aller voir un médecin. C''est une question d''égalité entre les citoyens.<break time="600ms"/>Bien sûr, on pourrait m''objecter que tout cela coûte très cher à la collectivité. Et c''est vrai, je le reconnais. Si personne ne paie son ticket, il faut bien que cet argent vienne de quelque part : en général, ce sont les impôts des habitants. Certaines personnes pensent aussi que la gratuité pourrait entraîner des dégradations ou un manque de respect du matériel.<break time="600ms"/>Cependant, malgré ces objections, je reste convaincu que les bénéfices sont plus importants que les inconvénients. À condition que le réseau soit bien organisé et correctement financé, la gratuité peut vraiment améliorer la vie quotidienne des habitants et protéger l''environnement. Pour conclure, je dirais que je suis plutôt favorable à cette idée, mais qu''il faut la mettre en place progressivement, et l''adapter à la taille et aux moyens de chaque ville. Voilà, c''était mon opinion sur ce sujet.</prosody></voice></speak>',
             '["Introduction : sujet + position", "Argument 1 (environnement) + exemple", "Argument 2 (justice sociale) + exemples", "Objection (coût, dégradations)", "Réponse à l''objection", "Conclusion nuancée (subjonctif) + adaptation par ville"]'::jsonb,
             'B1', 0
         );

END $$;